<template><div v-if="loading || error || empty" class="chapter-state" role="status" :aria-busy="loading"><span class="state-mark" aria-hidden="true">{{loading?'阅':error?'候':'藏'}}</span><div><h3>{{loading?'正在翻阅这一卷…':error?'这一页，暂时未能展开':'这一卷，静候新的故事'}}</h3><p>{{loading?'正在获取已发布的文化资料。':error?'资料暂时连接不上，你的筛选条件已保留。':'暂未找到符合当前条件的内容，可以清除筛选后再看看。'}}</p><button v-if="!loading" @click="$emit(error?'retry':'reset')">{{error?'重新加载 ↗':'清除筛选 ↗'}}</button></div></div></template>
<script setup>defineProps({loading:Boolean,error:[String,Boolean],empty:Boolean});defineEmits(['retry','reset'])</script>
<style scoped>.chapter-state{display:flex;align-items:center;justify-content:center;gap:30px;min-height:210px;padding:30px 20px;border-block:1px solid #d8cebd;background:#fffcf580;color:var(--brand-ink)}.state-mark{font:42px var(--brand-serif);color:#79887c;border:1px solid #a7ae9e;outline:1px solid #a7ae9e;outline-offset:4px;padding:10px}.chapter-state h3{font:23px var(--brand-serif);margin:0 0 12px}.chapter-state p{font:12px/1.8 var(--brand-sans);color:#756e63;margin:0 0 12px}.chapter-state button{background:none;border:0;border-bottom:1px solid var(--brand-red);padding:5px 0;color:var(--brand-red);font:12px var(--brand-sans);cursor:pointer}.chapter-state button:focus-visible{outline:2px solid var(--brand-red);outline-offset:4px}@media(max-width:600px){.chapter-state{gap:18px}.state-mark{font-size:26px}.chapter-state h3{font-size:19px}}</style>
